static uint8_t s_lang = LANG_EN;

void lang_set(uint8_t lang) { s_lang = (lang == LANG_IT) ? LANG_IT : LANG_EN; }
uint8_t lang_get(void) { return s_lang; }

const char *tr(int id) {
    if (id < 0 || id >= STR__COUNT) return "";
    if (s_lang == LANG_IT && strings[id].it != NULL) return strings[id].it;
    return strings[id].en;
}
